CREATE SCHEMA ref;
CREATE SCHEMA trd;
CREATE SCHEMA ops;
CREATE SCHEMA mkt;
CREATE SCHEMA eng;
CREATE TABLE ref.calendar (biz_date DATE NOT NULL, day_index INT NOT NULL, month_key CHAR(7) NOT NULL, is_month_end BIT NOT NULL);
CREATE TABLE ref.product (product_code VARCHAR(8) NOT NULL, product_name VARCHAR(60) NOT NULL, curve_ccy CHAR(3) NOT NULL, unit VARCHAR(4) NOT NULL);
CREATE TABLE ref.counterparty (cp_id INT NOT NULL, cp_code VARCHAR(10) NOT NULL, cp_name VARCHAR(80) NOT NULL, country CHAR(2) NOT NULL, segment VARCHAR(10) NOT NULL, grade CHAR(1) NOT NULL, has_netting BIT NOT NULL, payment_terms_days INT NOT NULL, we_deliver_first BIT NOT NULL);
CREATE TABLE ref.credit_limit (cp_id INT NOT NULL, approved_limit_myr DECIMAL(18,2) NOT NULL);
CREATE TABLE ref.collateral (cp_id INT NOT NULL, collateral_type VARCHAR(5) NOT NULL, amount_myr DECIMAL(18,2) NOT NULL);
CREATE TABLE ref.ecl_rate (grade CHAR(1) NOT NULL, ageing_band VARCHAR(6) NOT NULL, rate DECIMAL(8,4) NOT NULL);
CREATE TABLE trd.physical_contract (contract_id INT NOT NULL, contract_ref VARCHAR(10) NOT NULL, cp_id INT NOT NULL, product_code VARCHAR(8) NOT NULL, side CHAR(1) NOT NULL, trade_date DATE NOT NULL, delivery_date DATE NOT NULL, price_ccy CHAR(3) NOT NULL, terms VARCHAR(20) NOT NULL, is_mspo BIT NOT NULL, confirmed_price DECIMAL(12,2) NOT NULL, confirmed_qty_mt DECIMAL(12,3) NOT NULL);
CREATE TABLE trd.contract_version (contract_id INT NOT NULL, version_no INT NOT NULL, valid_from DATE NOT NULL, quantity_mt DECIMAL(12,3) NOT NULL, price DECIMAL(12,2) NOT NULL, status VARCHAR(10) NOT NULL, change_reason VARCHAR(10) NOT NULL);
CREATE TABLE trd.futures_trade (trade_id INT NOT NULL, trade_ref VARCHAR(10) NOT NULL, trade_date DATE NOT NULL, contract_month CHAR(7) NOT NULL, side CHAR(1) NOT NULL, lots INT NOT NULL, price_myr DECIMAL(12,2) NOT NULL, hedge_rel_id INT NULL, close_date DATE NULL, close_price DECIMAL(12,2) NULL);
CREATE TABLE trd.hedge_relationship (hedge_rel_id INT NOT NULL, designation_date DATE NOT NULL, product_code VARCHAR(8) NOT NULL, forecast_month CHAR(7) NOT NULL, forecast_qty_mt DECIMAL(12,3) NOT NULL, designated_lots INT NOT NULL, hedge_ratio DECIMAL(8,4) NOT NULL, documented BIT NOT NULL, hedge_type VARCHAR(10) NOT NULL);
CREATE TABLE ops.actualisation (actual_id INT NOT NULL, contract_id INT NOT NULL, actual_date DATE NOT NULL, quantity_mt DECIMAL(12,3) NOT NULL, actual_price DECIMAL(12,2) NOT NULL, quality_adj_pct DECIMAL(8,4) NOT NULL, recorded_date DATE NOT NULL);
CREATE TABLE ops.invoice (invoice_id INT NOT NULL, contract_id INT NOT NULL, cp_id INT NOT NULL, invoice_date DATE NOT NULL, due_date DATE NOT NULL, currency CHAR(3) NOT NULL, amount_ccy DECIMAL(18,2) NOT NULL, amount_myr DECIMAL(18,2) NOT NULL, side CHAR(1) NOT NULL);
CREATE TABLE ops.payment (payment_id INT NOT NULL, invoice_id INT NOT NULL, payment_date DATE NOT NULL, amount_myr DECIMAL(18,2) NOT NULL);
CREATE TABLE mkt.curve (curve_date DATE NOT NULL, product_code VARCHAR(8) NOT NULL, tenor_month CHAR(7) NOT NULL, price DECIMAL(12,2) NOT NULL, published_at DATE NOT NULL, version INT NOT NULL);
CREATE TABLE mkt.fx_rate (rate_date DATE NOT NULL, ccy_pair CHAR(6) NOT NULL, rate DECIMAL(12,6) NOT NULL);
CREATE TABLE mkt.monthly_history (month_key CHAR(7) NOT NULL, series VARCHAR(8) NOT NULL, price DECIMAL(12,6) NOT NULL, unit CHAR(3) NOT NULL);
